+/* Does this LCID relate to CCCH? */
+static gboolean is_ccch_lcid(uint8_t lcid, uint8_t direction)
+{
+    if (lcid==0) {
+        return TRUE;
+    }
+    else {
+        /* Extra UL CCCH LCIDs */
+        return (direction == DIRECTION_UPLINK) && (lcid>=11 && lcid<=13);
+    }
